import{_ as e,a0 as o,w as p,s as P,I as t,x as i,a1 as r,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？ | LCTT x X-CMD","titleTemplate":false,"description":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM","title":"PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？","tag":"201504","desc":""},"relativePath":"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM.md","filePath":"[post].md"}'),H={name:"201504/20141226 Real-World WordPress Benchmarks with PHP5.5 PHP5.6 PHP-NG and HHVM.md"};function d(g,l,u,m,h,M){const s=o("Link");return p(),P("div",null,[l[16]||(l[16]=t("h1",{id:"php-5-5-php5-6-php-ng-和-hhvm-哪个性能更好",tabindex:"-1"},[i("PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？ "),t("a",{class:"header-anchor",href:"#php-5-5-php5-6-php-ng-和-hhvm-哪个性能更好","aria-label":"Permalink to “PHP 5.5 / PHP5.6 / PHP-NG 和 HHVM 哪个性能更好？”"},"​")],-1)),l[17]||(l[17]=t("p",null,[t("strong",null,"长篇摘要：在一个基于Vagrant的本地环境中，可能是某个错误的原因，导致HHVM测试结果很差；在HHVM伙伴们协助下，该原因仍在研究中！然而，在DigitalOcean的一个4GB虚拟机中，HHVM甚至盖过了最新版的PHP-NG的风头！")],-1)),l[18]||(l[18]=t("p",null,[t("img",{src:"https://kinsta.com/wp-content/uploads/2014/07/phphhvm.jpg",alt:""})],-1)),l[19]||(l[19]=t("p",null,[t("strong",null,"结论：它们反映出HHVM的功效更佳（在JIT热启动后），虽然出于某些原因，我们不能在所有装备中获取这些结果。")],-1)),t("p",null,[l[1]||(l[1]=i("如果你记得我们",-1)),r(s,{href:"https://kinsta.com/blog/hhvm-and-wordpress/"},{default:n(()=>[...l[0]||(l[0]=[i("在几个月前写过一篇文章",-1)])]),_:1}),l[2]||(l[2]=i("，那时WordPress 3.9表明是完全支持HHVM的，当时是那么令我们欢欣鼓舞。最初的基准测试结果显示，HHVM要比驱动着当前所有PHP构建的Zend引擎高级得多。后来，问题就出来了：",-1))]),l[20]||(l[20]=a(`<ul><li>HHVM只能以单个用户运行，这意味着（在共享环境中）安全性差了</li><li>HHVM在崩溃后不会自动重启，而不幸的是，它至今仍然经常发生</li><li>HHVM在启动时使用大量内存，虽然，它和同规模的PHP-FPM比较，单个请求的内存使用量更低</li></ul><p>很显然，你不得不根据你的（或者更确切地说是你的站点）的需求采取折中方案，然而这值得吗？切换到HHVM后，你期望获得多少性能改善呢？</p><p>在Kinsta，我们真的想要测试所有新技术，并通常会优化这一切来为我们的客户提供最佳的环境。今天，我最终花了点时间来配置测试环境并进行了一些测试来对比两个不同的构建，一个是全新出炉的WordPress安装，另外一个则添加了大量内容的WooCommerce！为了计量脚本的运行时间，我只是简单地添加了</p><pre><code>&lt;?php timer_stop(1); ?&gt;
</code></pre><p>这一行到footer.php的/body标记前。</p><p>这里是配置环境的详情：</p><ul><li>DigitalOcean 4GB 雨滴容器 (2 CPU核心, 4GB RAM)</li><li>Ubuntu 14.04, MariaDB10</li><li>测试站点： 已导入演示内容的Munditia主题，WooCommerce 2.1.12 &amp; WordPress 3.9.1</li><li>PHP 5.5.9, PHP 5.5.15, PHP 5.6.0 RC2, PHP-NG （20140718-git-6cc487d）和HHVM 3.2.0 （版本是PHP 5.6.99-hhvm）</li></ul><p><strong>没有进一步大费周章，这些就是我的测试结果，数值越低越好，以秒为单位：</strong></p><h3 id="digitalocean-4gb-雨滴容器" tabindex="-1">DigitalOcean 4GB 雨滴容器 <a class="header-anchor" href="#digitalocean-4gb-雨滴容器" aria-label="Permalink to “DigitalOcean 4GB 雨滴容器”">​</a></h3><p>单位是秒，运行10次，越低越好</p><p>这里有一个canvas的数据，发布的时候需要截一个图</p><p>看起来似乎PHP-NG在它首次运行后就获得了峰值性能！HHVM需要更多几次重载，但是它们的性能貌似差不多！我等不及PHP-NG合并到开发主干了！：）</p><p>一分钟命中数，越高越好。</p><p>这里有一个canvas的数据，发布的时候需要截一个图</p><p><strong>PHP 5.5.15禁用OpCache</strong></p><ul><li>执行： <strong>236 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.03 secs</li><li>传输的数据： 2.40 MB</li><li>回应时间： 2.47 secs</li><li>执行率： 4.00 trans/sec</li><li>吞吐量： 0.04 MB/sec</li><li>并发数： 9.87</li><li>成功的执行： 236</li><li>失败的执行： 0</li><li>最长执行： 4.44</li><li>最短执行： 0.48</li></ul><p><strong>PHP 5.5.15启用OpCache</strong></p><ul><li>执行： <strong>441 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.55 secs</li><li>传输的数据： 4.48 MB</li><li>回应时间： 1.34 secs</li><li>执行率： 7.41 trans/sec</li><li>吞吐量： 0.08 MB/sec</li><li>并发数： 9.91</li><li>成功的执行： 441</li><li>失败的执行： 0</li><li>最长执行： 2.19</li><li>最短执行： 0.64</li></ul><p><strong>PHP 5.6 RC2禁用OpCache</strong></p><ul><li>执行： <strong>207 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.87 secs</li><li>传输的数据： 2.10 MB</li><li>回应时间： 2.80 secs</li><li>执行率： 3.46 trans/sec</li><li>吞吐量： 0.04 MB/sec</li><li>并发数： 9.68</li><li>成功的执行： 207</li><li>失败的执行： 0</li><li>最长执行： 3.65</li><li>最短执行： 0.54</li></ul><p><strong>PHP 5.6 RC2启用OpCache</strong></p><ul><li>执行： <strong>412 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.03 secs</li><li>传输的数据： 4.18 MB</li><li>回应时间： 1.42 secs</li><li>执行率： 6.98 trans/sec</li><li>吞吐量： 0.07 MB/sec</li><li>并发数： 9.88</li><li>成功的执行： 412</li><li>失败的执行： 0</li><li>最长执行： 1.93</li><li>最短执行： 0.34</li></ul><p><strong>HHVM 3.2.0（版本是PHP 5.6.99-hhvm）</strong></p><ul><li>执行： <strong>955 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.69 secs</li><li>传输的数据： 9.18 MB</li><li>回应时间： 0.62 secs</li><li>执行率： 16.00 trans/sec</li><li>吞吐量： 0.15 MB/sec</li><li>并发数： 9.94</li><li>成功的执行： 955</li><li>失败的执行： 0</li><li>最长执行： 0.85</li><li>最短执行： 0.23</li></ul><p><strong>PHP-NG启用OpCache（构建: Jul 29 2014）</strong></p><ul><li>执行： <strong>849 hits</strong></li><li>可用性： 100.00 %</li><li>消耗时间： 59.88 secs</li><li>传输的数据： 8.63 MB</li><li>回应时间： 0.70 secs</li><li>执行率： 14.18 trans/sec</li><li>吞吐量： 0.14 MB/sec</li><li>并发数： 9.94</li><li>成功的执行： 849</li><li>失败的执行： 0</li><li>最长执行： 1.06</li><li>最短执行： 0.13</li></ul><p><strong>注意：这里节略了前一次的测试结果（有误），如感兴趣请访问原文查看。</strong></p><hr>`,28)),t("p",null,[l[4]||(l[4]=i("via: ",-1)),r(s,{href:"https://kinsta.com/blog/real-world-wordpress-benchmarks-with-php5-5-php5-6-php-ng-and-hhvm/"},{default:n(()=>[...l[3]||(l[3]=[i("https://kinsta.com/blog/real-world-wordpress-benchmarks-with-php5-5-php5-6-php-ng-and-hhvm/",-1)])]),_:1})]),t("p",null,[l[8]||(l[8]=i("作者：",-1)),r(s,{href:"https://kinsta.com/blog/author/kinstadmin/"},{default:n(()=>[...l[5]||(l[5]=[i("Mark Gavalda",-1)])]),_:1}),l[9]||(l[9]=i(" 译者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:n(()=>[...l[6]||(l[6]=[i("GOLinux",-1)])]),_:1}),l[10]||(l[10]=i(" 校对：",-1)),r(s,{href:"https://github.com/wxy"},{default:n(()=>[...l[7]||(l[7]=[i("wxy",-1)])]),_:1})]),t("p",null,[l[13]||(l[13]=i("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[11]||(l[11]=[i("LCTT",-1)])]),_:1}),l[14]||(l[14]=i(" 原创翻译，",-1)),r(s,{href:"http://linux.cn/"},{default:n(()=>[...l[12]||(l[12]=[i("Linux中国",-1)])]),_:1}),l[15]||(l[15]=i(" 荣誉推出",-1))])])}const B=e(H,[["render",d]]);export{f as __pageData,B as default};
